// Metadata for the PingOne sample apps, one entry per use case.
//
// The code snippets live in sampleCode.json (generated by
// scripts/extract-sample-code.py). This file carries everything a reader needs
// around that code: what the sample teaches, what it needs, and what it cannot do.
//
// Roles are the CORRECTED values. The sample repo's AGENTS.md gets two of them
// wrong — it says Organization Admin for custom-admin-role, and names a
// "PingOne Protect" role that does not exist for m2m-credentials. Granting
// Organization Admin succeeds, so nothing errors; the tenant is just
// over-privileged. Use the values below.

export const STACKS = [
  { id: "js", label: "Node.js" },
  { id: "python", label: "Python" },
  { id: "go", label: "Go" },
  { id: "react", label: "React" },
  { id: "angular", label: "Angular" },
];

export const SAMPLE_APPS = [
  {
    id: "m2m-credentials",
    path: "/samples/m2m-credentials",
    label: "M2M Client Credentials",
    tagline: "Service-to-service OAuth, with a Protect risk check gating the call",
    summary:
      "The client_credentials grant is the right choice whenever there is no human user. " +
      "A backend service authenticates with its own credentials, gets an access token, and " +
      "calls PingOne APIs with it. No browser redirect, no authorization code, no PKCE.",
    teaches: [
      "Why client_credentials is the correct grant for machine-to-machine calls",
      "How to validate a PingOne access token properly — JWKS, RS256 signature, then claims",
      "Why you must check client_id and not sub: worker tokens have no subject",
      "How PingOne Protect scores an event, and how to gate a call on the result",
    ],
    roles: ["Identity Data Read Only", "Environment Admin"],
    rolesNote:
      "Environment Admin is needed to create risk evaluations. There is no Protect-specific role — Protect is environment-scoped.",
    runnable: "full",
    runNote: "Runs end-to-end against the configured environment. Creates nothing.",
    writes: false,
    runnerHref: "/m2m-sample",
  },
  {
    id: "custom-admin-role",
    path: "/samples/custom-admin-role",
    label: "Custom Admin Role",
    tagline: "Delegated administration — a narrow role, scoped to one environment",
    summary:
      "PingOne's built-in platform roles cannot be modified. Custom admin roles let you build a " +
      "narrower one — an application manager that can read and update apps but not delete them — " +
      "and assign it at environment scope. This is the standard delegated-administration pattern.",
    teaches: [
      "How to create a custom admin role from a chosen subset of permissions",
      "What canBeAssignedBy does, and why it is what makes delegation safe",
      "Why scope.type=ENVIRONMENT keeps a delegated role from becoming a global one",
      "Why the sample hardcodes the Environment Admin role ID instead of looking it up",
    ],
    roles: ["Environment Admin"],
    rolesNote:
      "Environment Admin is sufficient. Do NOT grant Organization Admin — the sample is deliberately built to avoid needing it.",
    runnable: "full",
    runNote:
      "Runs end-to-end against the configured environment. It creates a custom role and a demo worker app — the upstream sample leaves both behind, so this page deletes them afterwards unless you say otherwise.",
    writes: true,
    runnerApi: "/api/custom-admin-role-sample",
    runLabel: "Run the workflow",
    cleanupLabel: "Delete the role and app afterwards (recommended)",
  },
  {
    id: "user-registration",
    path: "/samples/user-registration",
    label: "User Registration",
    tagline: "Self-service sign-up with email verification, then an OIDC sign-in",
    summary:
      "A native flow (response_mode=pi.flow) drives registration server-side: create the user, " +
      "verify their email with a one-time code, then resume the flow to get an authorization " +
      "code and exchange it for tokens. No browser redirect is involved at any point.",
    teaches: [
      "How response_mode=pi.flow replaces the browser redirect with a server-driven flow",
      "Why the vendor content types matter — application/json returns 415",
      "How /as/resume converts a completed flow into an ordinary authorization code",
      "That redirect_uri here is a parameter echo, not an endpoint anyone visits",
    ],
    roles: ["Identity Data Admin", "Environment Admin"],
    rolesNote:
      "Identity Data Admin creates the OIDC app, population and sign-on policy; Environment Admin enables self-registration.",
    runnable: "partial",
    runNote:
      "Runs as far as the email verification step. Completing it needs a real inbox to receive the one-time code — there is no mock.",
    writes: true,
  },
  {
    id: "mfa-demo",
    path: "/samples/mfa-demo",
    label: "Login with MFA",
    tagline: "Sign-in with an email MFA challenge, driven entirely server-side",
    summary:
      "The same native-flow mechanism as registration, applied to sign-in: submit credentials, " +
      "handle the MFA challenge PingOne returns, check the one-time passcode, then resume for " +
      "tokens. The flow's session cookies must be captured and replayed by hand.",
    teaches: [
      "How a native flow signals that MFA is required, and the statuses to branch on",
      "That /flows/{id} needs BOTH a worker bearer token AND the replayed session cookies",
      "Why the sample manages cookies manually instead of relying on a cookie jar",
      "Why this sample validates credentials at startup and refuses to boot without them",
    ],
    roles: ["Identity Data Admin", "Environment Admin"],
    rolesNote:
      "Also requires Email to be enabled in the environment's default device authentication policy, or enrollment fails.",
    runnable: "partial",
    runNote:
      "Runs as far as the MFA challenge. Completing it needs a real inbox to receive the passcode — there is no mock.",
    writes: true,
  },
];

export function getSampleApp(id) {
  return SAMPLE_APPS.find((a) => a.id === id) || null;
}
